mapper.select:
SELECT * FROM (
  SELECT p.id AS transaction_id, 'PAYMENT' AS transaction_type, mp.name AS product_name, p.payment_method, p.amount, p.status, p.paid_at AS occurred_at
  FROM payments p JOIN members m ON m.id=p.member_id LEFT JOIN member_memberships mm ON mm.id=p.member_membership_id LEFT JOIN membership_products mp ON mp.id=mm.product_id WHERE m.user_id=#{userId}
  UNION ALL
  SELECT r.id, 'REFUND', mp.name, p.payment_method, r.amount, r.status, r.refunded_at
  FROM refunds r JOIN payments p ON p.id=r.payment_id JOIN members m ON m.id=p.member_id LEFT JOIN member_memberships mm ON mm.id=p.member_membership_id LEFT JOIN membership_products mp ON mp.id=mm.product_id WHERE m.user_id=#{userId}
) history ORDER BY occurred_at DESC, transaction_id DESC
